rsqrt_dist:
src/shaders.hlsl
    float fDist = length(vLightToPixelUnNormalized);
    float fDistSq = dot(vLightToPixelUnNormalized, vLightToPixelUnNormalized);
    float fInvDist = rsqrt(fDistSq);
    float fDist = fDistSq * fInvDist;
src/shaders.hlsl
    float3 vLightToPixelNormalized = vLightToPixelUnNormalized / fDist;
    float3 vLightToPixelNormalized = vLightToPixelUnNormalized * fInvDist;

light_dir_norm:
src/shaders.hlsl
    float fCosAngle = dot(vLightToPixelNormalized, vLightDir / length(vLightDir));
    float fCosAngle = dot(vLightToPixelNormalized, vLightDir)
                    * rsqrt(dot(vLightDir, vLightDir));

